def scan_number_candidates(fragment):
    number_candidates = []
    index = 0
    while index < len(fragment):
        if not fragment[index].isdigit():
            index += 1
            continue
        start = index
        while index < len(fragment) and (fragment[index].isdigit() or fragment[index] in ',.'):
            index += 1
        raw_number = fragment[start:index].strip('.,')
        cleaned_number = raw_number.replace(',', '')
        if not cleaned_number or cleaned_number.count('.') > 1 or not cleaned_number.replace('.', '').isdigit():
            continue
        before = fragment[max(0, start - 12):start].lower()
        after = fragment[index:min(len(fragment), index + 8)].lower()
        decimal_places = len(cleaned_number.split('.')[1]) if '.' in cleaned_number else 0
        currency_marked = any(symbol in before for symbol in ('$','£','€')) or any(code in before or code in after for code in ('usd','ttd','cad','aud','eur','gbp'))
        money_like = currency_marked or ('.' in cleaned_number and 1 <= decimal_places <= 2) or ',' in raw_number
        compact_before = ''.join(before.split())
        value = float(cleaned_number)
        if compact_before.endswith('$-') or compact_before.endswith('£-') or compact_before.endswith('€-') or compact_before.endswith('(') or compact_before.endswith('($'):
            value = -value
        number_candidates.append((value, money_like))
    return number_candidates

